    const event_type_ref01_markdef_up0 = { name: 'bookingUrl', value: 'Mark01-event_type_ref01_' + setup.now }
    ;(event_type_ref01_data_up0 as any)[event_type_ref01_markdef_up0.name] = event_type_ref01_markdef_up0.value

